window.LAB_LIBRARY={"papers":[{"id":"pub00001","ax":"2609.02734","key":null,"t":"LoRA-TSD: Tangent-Space Spectral Descent for LoRA via Muon-Style Updates","au":"Dmitrii Andriianov, Andrey Veprikov, Aleksandr Beznosikov","y":2026,"v":"Preprint · arXiv","s":"LoRA-TSD transfers Muon's spectral step to the tangent space of fixed-rank matrices. The update is mapped back to LoRA factors without operating on the full weight matrix.","sr":"LoRA-TSD transfers Muon's spectral step to the tangent space of fixed-rank matrices. The update is mapped back to LoRA factors without operating on the full weight matrix.","ab":"LoRA-TSD transfers Muon's spectral step to the tangent space of fixed-rank matrices. The update is mapped back to LoRA factors without operating on the full weight matrix.","f":"Andrey's publications/Papers and preprints","th":null,"nc":4,"ns":1,"nm":0,"c":[{"k":"method","s":"LoRA-TSD constructs a step in the tangent space of the LoRA update matrix and chooses a descent direction under the spectral norm.","q":"","v":false,"source_url":"https://arxiv.org/abs/2609.02734","locator":"arXiv abstract"},{"k":"method","s":"A specialized retraction maps the tangent step back to LoRA factors without expensive operations on the full weight matrix.","q":"","v":false,"source_url":"https://arxiv.org/abs/2609.02734","locator":"arXiv abstract"},{"k":"theoretical","s":"For the Frobenius-norm variant, the authors recover LoRA-Pro. Convergence of LoRA-Pro and LoRA-TSD is analyzed through the Riemannian gradient.","q":"","v":false,"source_url":"https://arxiv.org/abs/2609.02734","locator":"arXiv abstract"},{"k":"empirical","s":"Across six commonsense and reasoning tasks with Llama-3.2-1B, Llama-3.1-8B and Qwen3-32B, the authors report that LoRA-TSD outperforms the compared LoRA optimizers.","q":"","v":false,"source_url":"https://arxiv.org/abs/2609.02734","locator":"arXiv abstract"}],"origin":"author-publication","source_url":"https://arxiv.org/abs/2609.02734","venue_url":"https://arxiv.org/abs/2609.02734","code_url":"https://github.com/brain-lab-research/LoRA-TSD","reading_scope":"arXiv abstract"},{"id":"pub00002","ax":"2605.31371","key":null,"t":"Softsign: Smooth Sign in Your Optimizer For Better Parameter Heterogeneity Handling","au":"Dmitrii Feoktistov, Timofey Belinsky, Andrey Veprikov, Amir Zainullin, Aleksandr Beznosikov","y":2026,"v":"ICML 2026","s":"Softsign replaces the hard gradient sign with a smooth function. Temperature controls how much gradient magnitude the update retains. SoftMuon extends the approach to matrix parameters.","sr":"Softsign replaces the hard gradient sign with a smooth function. Temperature controls how much gradient magnitude the update retains. SoftMuon extends the approach to matrix parameters.","ab":"Softsign replaces the hard gradient sign with a smooth function. Temperature controls how much gradient magnitude the update retains. SoftMuon extends the approach to matrix parameters.","f":"Andrey's publications/Papers and preprints","th":null,"nc":5,"ns":1,"nm":0,"c":[{"k":"method","s":"SoftSignum smooths the gradient sign. Temperature controls the transition from an almost sign-based step to one sensitive to gradient magnitude.","q":"","v":false,"source_url":"https://arxiv.org/abs/2605.31371","locator":"arXiv abstract"},{"k":"method","s":"Quantile-based temperature adaptation adjusts Softsign to the distribution of gradient magnitudes and parameter heterogeneity.","q":"","v":false,"source_url":"https://arxiv.org/abs/2605.31371","locator":"arXiv abstract"},{"k":"method","s":"SoftMuon extends the smooth-sign idea to Muon's matrix updates.","q":"","v":false,"source_url":"https://arxiv.org/abs/2605.31371","locator":"arXiv abstract"},{"k":"theoretical","s":"The authors connect smoothed directions to strongly convex regularization and prove convergence in a nonconvex stochastic setting.","q":"","v":false,"source_url":"https://arxiv.org/abs/2605.31371","locator":"arXiv abstract"},{"k":"empirical","s":"In the reported experiments, including language model training, Softsign improves on the sign-based optimizers used for comparison.","q":"","v":false,"source_url":"https://arxiv.org/abs/2605.31371","locator":"arXiv abstract"}],"origin":"author-publication","source_url":"https://arxiv.org/abs/2605.31371","venue_url":"https://icml.cc/Downloads/2026","code_url":"https://github.com/brain-lab-research/softsign","reading_scope":"arXiv abstract"},{"id":"pub00003","ax":"2605.22644","key":null,"t":"Why SGD is not Brownian Motion: A New Perspective on Stochastic Dynamics","au":"Igor Ignashin, Anna Radovskaya, Andrew Semenov, Egor Lopatin, Stanislav Potapov, Aleksandr Kovalenko, Andrey Veprikov, Aleksandr Shestakov, Andrey Leonidov, Aleksandr Beznosikov","y":2026,"v":"Preprint · arXiv","s":"The paper studies the stochastic dynamics of SGD at a finite learning rate. Discrete training is modeled through fluctuations in the loss landscape, rather than only a continuous Brownian approximation.","sr":"The paper studies the stochastic dynamics of SGD at a finite learning rate. Discrete training is modeled through fluctuations in the loss landscape, rather than only a continuous Brownian approximation.","ab":"The paper studies the stochastic dynamics of SGD at a finite learning rate. Discrete training is modeled through fluctuations in the loss landscape, rather than only a continuous Brownian approximation.","f":"Andrey's publications/Papers and preprints","th":null,"nc":4,"ns":1,"nm":0,"c":[{"k":"theoretical","s":"The discrete Fokker–Planck equation for SGD differs from the continuous Langevin approximation in terms that are second order in the learning rate.","q":"","v":false,"source_url":"https://arxiv.org/abs/2605.22644","locator":"arXiv abstract"},{"k":"theoretical","s":"An eigendirection decomposition near a critical point describes how curvature affects fluctuations of SGD parameters.","q":"","v":false,"source_url":"https://arxiv.org/abs/2605.22644","locator":"arXiv abstract"},{"k":"theoretical","s":"In flat directions, the model predicts variance growth with a diffusion coefficient that depends on the learning rate.","q":"","v":false,"source_url":"https://arxiv.org/abs/2605.22644","locator":"arXiv abstract"},{"k":"empirical","s":"The model's predictions are compared with computer vision and language experiments, testing the SGD regimes studied.","q":"","v":false,"source_url":"https://arxiv.org/abs/2605.22644","locator":"arXiv abstract"}],"origin":"author-publication","source_url":"https://arxiv.org/abs/2605.22644","venue_url":"https://arxiv.org/abs/2605.22644","code_url":null,"reading_scope":"arXiv abstract"},{"id":"pub00004","ax":"2605.19811","key":null,"t":"LionMuon: Alternating Spectral and Sign Descent for Efficient Training","au":"Arman Bolatov, Artem Riabinin, Nikita Kornilov, Andrey Veprikov, Samuel Horváth, Martin Takáč, Aleksandr Beznosikov","y":2026,"v":"Preprint · arXiv","s":"LionMuon alternates Muon's spectral steps with Lion's sign-based steps. One shared momentum buffer combines directions with different computational costs.","sr":"LionMuon alternates Muon's spectral steps with Lion's sign-based steps. One shared momentum buffer combines directions with different computational costs.","ab":"LionMuon alternates Muon's spectral steps with Lion's sign-based steps. One shared momentum buffer combines directions with different computational costs.","f":"Andrey's publications/Papers and preprints","th":null,"nc":4,"ns":1,"nm":0,"c":[{"k":"method","s":"LionMuon periodically alternates Lion and Muon, using a shared momentum buffer rather than two independent optimizer states.","q":"","v":false,"source_url":"https://arxiv.org/abs/2605.19811","locator":"arXiv abstract"},{"k":"method","s":"The alternation period controls the fraction of expensive spectral steps. SignMuon uses a sign-based direction with one exponential moving average.","q":"","v":false,"source_url":"https://arxiv.org/abs/2605.19811","locator":"arXiv abstract"},{"k":"theoretical","s":"The convergence bound accounts for smoothness and noise properties averaged over the period, including heavy-tailed noise.","q":"","v":false,"source_url":"https://arxiv.org/abs/2605.19811","locator":"arXiv abstract"},{"k":"empirical","s":"In language model experiments, the authors show LionMuon settings with lower loss and lower compute cost than the selected baselines.","q":"","v":false,"source_url":"https://arxiv.org/abs/2605.19811","locator":"arXiv abstract"}],"origin":"author-publication","source_url":"https://arxiv.org/abs/2605.19811","venue_url":"https://arxiv.org/abs/2605.19811","code_url":null,"reading_scope":"arXiv abstract"},{"id":"pub00005","ax":"2602.16456","key":null,"t":"Beyond SGD, Without SVD: Proximal Subspace Iteration LoRA with Diagonal Fractional K-FAC","au":"Abdulla Jasem Almansoori, Maria Ivanova, Andrey Veprikov, Aleksandr Beznosikov, Samuel Horváth, Martin Takáč","y":2026,"v":"Preprint · arXiv","s":"The proximal LoRA update is solved by alternating steps over its factors. LoRSum connects this subspace iteration to diagonal fractional K-FAC and low-rank momentum.","sr":"The proximal LoRA update is solved by alternating steps over its factors. LoRSum connects this subspace iteration to diagonal fractional K-FAC and low-rank momentum.","ab":"The proximal LoRA update is solved by alternating steps over its factors. LoRSum connects this subspace iteration to diagonal fractional K-FAC and low-rank momentum.","f":"Andrey's publications/Papers and preprints","th":null,"nc":4,"ns":1,"nm":0,"c":[{"k":"method","s":"Alternating solution of the proximal LoRA problem is interpreted as an implicit block power iteration and avoids a full SVD.","q":"","v":false,"source_url":"https://arxiv.org/abs/2602.16456","locator":"arXiv abstract"},{"k":"method","s":"Diagonal fractional K-FAC preconditioners define the step geometry while preserving a low-rank update representation.","q":"","v":false,"source_url":"https://arxiv.org/abs/2602.16456","locator":"arXiv abstract"},{"k":"method","s":"LoRSum stores momentum in low-rank form so fine-tuning does not require a full matrix state again.","q":"","v":false,"source_url":"https://arxiv.org/abs/2602.16456","locator":"arXiv abstract"},{"k":"empirical","s":"The paper compares fine-tuning quality and cost on CIFAR-100, GLUE, SQuAD v2 and WikiText-103.","q":"","v":false,"source_url":"https://arxiv.org/abs/2602.16456","locator":"arXiv abstract"}],"origin":"author-publication","source_url":"https://arxiv.org/abs/2602.16456","venue_url":"https://arxiv.org/abs/2602.16456","code_url":null,"reading_scope":"arXiv abstract"},{"id":"pub00006","ax":"2602.13659","key":null,"t":"Zero-Order Optimization for LLM Fine-Tuning via Learnable Direction Sampling","au":"Valery Parfenov, Grigoriy Evseev, Andrey Veprikov, Nikolay Bushkov, Stanislav Moiseev, Aleksandr Beznosikov","y":2026,"v":"Preprint · arXiv","s":"A learned policy chooses directions for zeroth-order LLM fine-tuning. It changes the distribution of perturbations used to estimate a loss-improving direction.","sr":"A learned policy chooses directions for zeroth-order LLM fine-tuning. It changes the distribution of perturbations used to estimate a loss-improving direction.","ab":"A learned policy chooses directions for zeroth-order LLM fine-tuning. It changes the distribution of perturbations used to estimate a loss-improving direction.","f":"Andrey's publications/Papers and preprints","th":null,"nc":4,"ns":1,"nm":0,"c":[{"k":"method","s":"A learned policy for selecting parameter perturbations replaces a fixed random distribution of directions.","q":"","v":false,"source_url":"https://arxiv.org/abs/2602.13659","locator":"arXiv abstract"},{"k":"method","s":"The update direction is estimated from loss values and does not require backpropagation through the language model.","q":"","v":false,"source_url":"https://arxiv.org/abs/2602.13659","locator":"arXiv abstract"},{"k":"theoretical","s":"The analysis connects adaptation of the direction distribution to variance reduction and weaker explicit dimension dependence in the bounds.","q":"","v":false,"source_url":"https://arxiv.org/abs/2602.13659","locator":"arXiv abstract"},{"k":"empirical","s":"The benefits of learned directions are tested on the reported zeroth-order language model fine-tuning tasks.","q":"","v":false,"source_url":"https://arxiv.org/abs/2602.13659","locator":"arXiv abstract"}],"origin":"author-publication","source_url":"https://arxiv.org/abs/2602.13659","venue_url":"https://arxiv.org/abs/2602.13659","code_url":null,"reading_scope":"arXiv abstract"},{"id":"pub00007","ax":"2602.05813","key":null,"t":"Where Does Warm-Up Come From? Adaptive Scheduling for Norm-Constrained Optimizers","au":"Artem Riabinin, Andrey Veprikov, Arman Bolatov, Martin Takáč, Aleksandr Beznosikov","y":2026,"v":"Preprint · arXiv","s":"The paper derives warmup and subsequent learning-rate decay from a model of changing local curvature. The adaptive schedule is designed for optimizers with bounded direction norms.","sr":"The paper derives warmup and subsequent learning-rate decay from a model of changing local curvature. The adaptive schedule is designed for optimizers with bounded direction norms.","ab":"The paper derives warmup and subsequent learning-rate decay from a model of changing local curvature. The adaptive schedule is designed for optimizers with bounded direction norms.","f":"Andrey's publications/Papers and preprints","th":null,"nc":4,"ns":1,"nm":0,"c":[{"k":"theoretical","s":"Under the adopted generalized-smoothness model, local curvature decreases with the optimality gap. This provides a rationale for increasing the learning rate early in training.","q":"","v":false,"source_url":"https://arxiv.org/abs/2602.05813","locator":"arXiv abstract"},{"k":"method","s":"The adaptive schedule first increases and then decreases the learning rate. The update rule itself determines warmup duration.","q":"","v":false,"source_url":"https://arxiv.org/abs/2602.05813","locator":"arXiv abstract"},{"k":"method","s":"The warmup schedule uses standard optimizer parameters and requires no separate sweep over warmup duration.","q":"","v":false,"source_url":"https://arxiv.org/abs/2602.05813","locator":"arXiv abstract"},{"k":"empirical","s":"In Llama experiments, the authors obtain quality matching or exceeding the best manually tuned schedules under the settings studied.","q":"","v":false,"source_url":"https://arxiv.org/abs/2602.05813","locator":"arXiv abstract"}],"origin":"author-publication","source_url":"https://arxiv.org/abs/2602.05813","venue_url":"https://arxiv.org/abs/2602.05813","code_url":null,"reading_scope":"arXiv abstract"},{"id":"pub00008","ax":"2601.05398","key":null,"t":"Markovian Compression: Looking to the Past Helps Accelerate the Future","au":"Andrey Veprikov, Vladimir Solodkin, Mikhail Rudakov, Petr Babkin, Aleksandr Beznosikov","y":2026,"v":"UAI 2026","s":"Markov compression uses previous steps when communicating gradients. The paper examines QSGD and its momentum variant in terms of communication cost and convergence.","sr":"Markov compression uses previous steps when communicating gradients. The paper examines QSGD and its momentum variant in terms of communication cost and convergence.","ab":"Markov compression uses previous steps when communicating gradients. The paper examines QSGD and its momentum variant in terms of communication cost and convergence.","f":"Andrey's publications/Papers and preprints","th":null,"nc":4,"ns":1,"nm":0,"c":[{"k":"method","s":"The Markov compressor accounts for previous iterations, so compression errors are not modeled as independent at each step.","q":"","v":false,"source_url":"https://arxiv.org/abs/2601.05398","locator":"arXiv abstract"},{"k":"method","s":"The proposed approach is applied to quantized SGD and its momentum variant.","q":"","v":false,"source_url":"https://arxiv.org/abs/2601.05398","locator":"arXiv abstract"},{"k":"theoretical","s":"Convergence bounds are obtained for nonconvex and strongly convex problems and functions satisfying the Polyak–Łojasiewicz condition.","q":"","v":false,"source_url":"https://arxiv.org/abs/2601.05398","locator":"arXiv abstract"},{"k":"empirical","s":"Experiments with ResNet-18 on CIFAR-10 and DeBERTa-v3 on GLUE test how using compression history affects training.","q":"","v":false,"source_url":"https://arxiv.org/abs/2601.05398","locator":"arXiv abstract"}],"origin":"author-publication","source_url":"https://arxiv.org/abs/2601.05398","venue_url":"https://proceedings.mlr.press/v337/veprikov26a.html","code_url":null,"reading_scope":"arXiv abstract"},{"id":"pub00009","ax":"2511.06477","key":null,"t":"DyKAF: Dynamical Kronecker Approximation of the Fisher Information Matrix for Gradient Preconditioning","au":"Nikolay Yudin, Ekaterina Grishina, Andrey Veprikov, Alexandr Beznosikov, Maxim Rakhuba","y":2025,"v":"Preprint · arXiv","s":"DyKAF dynamically approximates the Fisher matrix with Kronecker factors. Factor updates use projector-splitting integrators and are used to precondition the gradient.","sr":"DyKAF dynamically approximates the Fisher matrix with Kronecker factors. Factor updates use projector-splitting integrators and are used to precondition the gradient.","ab":"DyKAF dynamically approximates the Fisher matrix with Kronecker factors. Factor updates use projector-splitting integrators and are used to precondition the gradient.","f":"Andrey's publications/Papers and preprints","th":null,"nc":4,"ns":1,"nm":0,"c":[{"k":"method","s":"DyKAF represents a Fisher matrix approximation through Kronecker factors and updates them during training.","q":"","v":false,"source_url":"https://arxiv.org/abs/2511.06477","locator":"arXiv abstract"},{"k":"method","s":"The dynamic approximation uses projector-splitting integrators, connecting factor updates to the geometry of a matrix manifold.","q":"","v":false,"source_url":"https://arxiv.org/abs/2511.06477","locator":"arXiv abstract"},{"k":"empirical","s":"The authors compare the accuracy of DyKAF's Kronecker approximation with alternatives on the tasks studied.","q":"","v":false,"source_url":"https://arxiv.org/abs/2511.06477","locator":"arXiv abstract"},{"k":"empirical","s":"The DyKAF preconditioner is tested in language model pretraining and fine-tuning. The results apply to the configurations reported in the paper.","q":"","v":false,"source_url":"https://arxiv.org/abs/2511.06477","locator":"arXiv abstract"}],"origin":"author-publication","source_url":"https://arxiv.org/abs/2511.06477","venue_url":"https://arxiv.org/abs/2511.06477","code_url":null,"reading_scope":"arXiv abstract"},{"id":"pub00010","ax":"2510.10777","key":null,"t":"Preconditioned Norms: A Unified Framework for Steepest Descent, Quasi-Newton and Adaptive Methods","au":"Andrey Veprikov, Arman Bolatov, Aleksandr Bogdanov, Samuel Horváth, Aleksandr Beznosikov, Martin Takáč, Slavomir Hanzely","y":2025,"v":"Preprint · arXiv","s":"Preconditioned norms combine the choice of descent geometry and preconditioner. The framework compares SGD, Adam, Muon and matrix-based second-order methods.","sr":"Preconditioned norms combine the choice of descent geometry and preconditioner. The framework compares SGD, Adam, Muon and matrix-based second-order methods.","ab":"Preconditioned norms combine the choice of descent geometry and preconditioner. The framework compares SGD, Adam, Muon and matrix-based second-order methods.","f":"Andrey's publications/Papers and preprints","th":null,"nc":4,"ns":1,"nm":0,"c":[{"k":"theoretical","s":"The steepest-descent direction is determined jointly by a norm and a preconditioner. Choosing these two components unifies several optimizer families.","q":"","v":false,"source_url":"https://arxiv.org/abs/2510.10777","locator":"arXiv abstract"},{"k":"theoretical","s":"The general framework examines conditions for affine and scale invariance of optimization methods.","q":"","v":false,"source_url":"https://arxiv.org/abs/2510.10777","locator":"arXiv abstract"},{"k":"method","s":"SGD, Adam, Muon, KL-Shampoo, SOAP and SPlus are interpreted as specific choices of norm and preconditioning.","q":"","v":false,"source_url":"https://arxiv.org/abs/2510.10777","locator":"arXiv abstract"},{"k":"method","s":"MuAdam and MuAdam-SANIA combine spectral geometry with Adam's adaptive scaling. The paper tests these variants experimentally.","q":"","v":false,"source_url":"https://arxiv.org/abs/2510.10777","locator":"arXiv abstract"}],"origin":"author-publication","source_url":"https://arxiv.org/abs/2510.10777","venue_url":"https://arxiv.org/abs/2510.10777","code_url":null,"reading_scope":"arXiv abstract"},{"id":"pub00011","ax":"2509.19977","key":null,"t":"Faster Than SVD, Smarter Than SGD: The OPLoRA Alternating Update","au":"Abdulla Jasem Almansoori, Maria Ivanova, Andrey Veprikov, Aleksandr Beznosikov, Samuel Horváth, Martin Takáč","y":2025,"v":"OPT 2025 · workshop","s":"OPLoRA updates adapter factors by alternating least-squares solves. This approximates a truncated SVD without constructing the full update matrix.","sr":"OPLoRA updates adapter factors by alternating least-squares solves. This approximates a truncated SVD without constructing the full update matrix.","ab":"OPLoRA updates adapter factors by alternating least-squares solves. This approximates a truncated SVD without constructing the full update matrix.","f":"Andrey's publications/Papers and preprints","th":null,"nc":4,"ns":1,"nm":0,"c":[{"k":"method","s":"OPLoRA alternates updates of LoRA factors rather than training them with independent gradient steps.","q":"","v":false,"source_url":"https://arxiv.org/abs/2509.19977","locator":"arXiv abstract"},{"k":"method","s":"One or two alternating least-squares steps approximate a truncated-SVD update without explicitly forming the full matrix.","q":"","v":false,"source_url":"https://arxiv.org/abs/2509.19977","locator":"arXiv abstract"},{"k":"method","s":"Low-rank momentum preserves the matrix direction in compact factors. K-FAC scaling is also considered.","q":"","v":false,"source_url":"https://arxiv.org/abs/2509.19977","locator":"arXiv abstract"},{"k":"empirical","s":"OPLoRA is tested on linear problems, MNIST, CIFAR-100 and RoBERTa fine-tuning on MNLI.","q":"","v":false,"source_url":"https://arxiv.org/abs/2509.19977","locator":"arXiv abstract"}],"origin":"author-publication","source_url":"https://arxiv.org/abs/2509.19977","venue_url":"https://arxiv.org/abs/2509.19977","code_url":null,"reading_scope":"arXiv abstract"},{"id":"pub00012","ax":"2508.16734","key":null,"t":"Aligning Distributionally Robust Optimization with Practical Deep Learning Needs","au":"Dmitrii Feoktistov, Igor Ignashin, Andrey Veprikov, Nikita Borovko, Alexander Bogdanov, Savelii Chezhegov, Aleksandr Beznosikov","y":2025,"v":"Preprint · arXiv","s":"ALSO adapts distributionally robust optimization to deep model training. Data groups receive changing weights to account for heterogeneous errors.","sr":"ALSO adapts distributionally robust optimization to deep model training. Data groups receive changing weights to account for heterogeneous errors.","ab":"ALSO adapts distributionally robust optimization to deep model training. Data groups receive changing weights to account for heterogeneous errors.","f":"Andrey's publications/Papers and preprints","th":null,"nc":4,"ns":1,"nm":0,"c":[{"k":"method","s":"The group distributionally robust formulation accounts for data groups on which the model makes larger errors.","q":"","v":false,"source_url":"https://arxiv.org/abs/2508.16734","locator":"arXiv abstract"},{"k":"method","s":"ALSO adaptively updates group weights and model parameters using stochastic gradients.","q":"","v":false,"source_url":"https://arxiv.org/abs/2508.16734","locator":"arXiv abstract"},{"k":"theoretical","s":"Convergence guarantees are obtained for the proposed algorithms in the nonconvex setting.","q":"","v":false,"source_url":"https://arxiv.org/abs/2508.16734","locator":"arXiv abstract"},{"k":"empirical","s":"The paper tests the approach on tasks ranging from tabular data to Split Learning.","q":"","v":false,"source_url":"https://arxiv.org/abs/2508.16734","locator":"arXiv abstract"}],"origin":"author-publication","source_url":"https://arxiv.org/abs/2508.16734","venue_url":"https://arxiv.org/abs/2508.16734","code_url":null,"reading_scope":"arXiv abstract"},{"id":"pub00013","ax":"2506.04430","key":null,"t":"Leveraging Coordinate Momentum in SignSGD and Muon: Memory-Optimized Zero-Order","au":"Egor Petrov, Grigoriy Evseev, Aleksey Antonov, Andrey Veprikov, Nikolay Bushkov, Stanislav Moiseev, Aleksandr Beznosikov","y":2025,"v":"Preprint · arXiv","s":"JAGUAR coordinate memory is used in zeroth-order variants of SignSGD and Muon. The goal is to update parameters using function values while retaining information about previously estimated coordinates.","sr":"JAGUAR coordinate memory is used in zeroth-order variants of SignSGD and Muon. The goal is to update parameters using function values while retaining information about previously estimated coordinates.","ab":"JAGUAR coordinate memory is used in zeroth-order variants of SignSGD and Muon. The goal is to update parameters using function values while retaining information about previously estimated coordinates.","f":"Andrey's publications/Papers and preprints","th":null,"nc":4,"ns":1,"nm":0,"c":[{"k":"method","s":"JAGUAR coordinate momentum reuses previous estimates rather than recomputing every coordinate at each step.","q":"","v":false,"source_url":"https://arxiv.org/abs/2506.04430","locator":"arXiv abstract"},{"k":"method","s":"A zeroth-order estimator with coordinate memory is applied to SignSGD's sign-based update and Muon's matrix update.","q":"","v":false,"source_url":"https://arxiv.org/abs/2506.04430","locator":"arXiv abstract"},{"k":"theoretical","s":"The analysis of the zeroth-order variants studies convergence with noisy function evaluations and a constant number of oracle queries per iteration.","q":"","v":false,"source_url":"https://arxiv.org/abs/2506.04430","locator":"arXiv abstract"},{"k":"empirical","s":"The methods are tested in memory-constrained language model fine-tuning, using function evaluations without storing the backpropagation graph.","q":"","v":false,"source_url":"https://arxiv.org/abs/2506.04430","locator":"arXiv abstract"}],"origin":"author-publication","source_url":"https://arxiv.org/abs/2506.04430","venue_url":"https://arxiv.org/abs/2506.04430","code_url":null,"reading_scope":"arXiv abstract"},{"id":"pub00014","ax":"2506.02724","key":null,"t":"WeightLoRA: Keep Only Necessary Adapters","au":"Andrey Veprikov, Vladimir Solodkin, Alexander Zyl, Andrey Savchenko, Aleksandr Beznosikov","y":2026,"v":"ACL 2026","s":"WeightLoRA selects which LoRA adapters a task needs. Learnable weights retain useful adapters and reduce the number of trainable parameters.","sr":"WeightLoRA selects which LoRA adapters a task needs. Learnable weights retain useful adapters and reduce the number of trainable parameters.","ab":"WeightLoRA selects which LoRA adapters a task needs. Learnable weights retain useful adapters and reduce the number of trainable parameters.","f":"Andrey's publications/Papers and preprints","th":null,"nc":4,"ns":1,"nm":0,"c":[{"k":"method","s":"WeightLoRA assigns learnable weights to adapters and uses them to select the LoRA adapters needed for the task.","q":"","v":false,"source_url":"https://aclanthology.org/2026.acl-long.566/","locator":"ACL 2026 abstract"},{"k":"method","s":"Adapter selection reduces the number of trainable parameters compared with placing LoRA in every preselected layer.","q":"","v":false,"source_url":"https://aclanthology.org/2026.acl-long.566/","locator":"ACL 2026 abstract"},{"k":"method","s":"WeightLoRA+ extends adapter selection while preserving the joint task of choosing adapter contributions and fine-tuning the model.","q":"","v":false,"source_url":"https://aclanthology.org/2026.acl-long.566/","locator":"ACL 2026 abstract"},{"k":"empirical","s":"The authors compare parameter count and quality on language understanding and generation tasks with DeBERTa, BART, Llama and Qwen. Adapter reduction is evaluated alongside response quality.","q":"","v":false,"source_url":"https://aclanthology.org/2026.acl-long.566/","locator":"ACL 2026 abstract"}],"origin":"author-publication","source_url":"https://arxiv.org/abs/2506.02724","venue_url":"https://aclanthology.org/2026.acl-long.566/","code_url":"https://github.com/brain-lab-research/WLoRA","reading_scope":"ACL 2026 abstract"},{"id":"pub00015","ax":"2409.10442","key":null,"t":"New Aspects of Black Box Conditional Gradient: Variance Reduction and One Point Feedback","au":"Andrey Veprikov, Aleksandr Bogdanov, Vladislav Minashkin, Aleksandr Beznosikov","y":2024,"v":"Chaos, Solitons & Fractals · 2024","s":"JAGUAR retains coordinate information for zeroth-order optimization. This memory enables conditional-gradient and gradient-descent updates with few new function evaluations.","sr":"JAGUAR retains coordinate information for zeroth-order optimization. This memory enables conditional-gradient and gradient-descent updates with few new function evaluations.","ab":"JAGUAR retains coordinate information for zeroth-order optimization. This memory enables conditional-gradient and gradient-descent updates with few new function evaluations.","f":"Andrey's publications/Papers and preprints","th":null,"nc":4,"ns":1,"nm":0,"c":[{"k":"method","s":"JAGUAR reuses earlier coordinate estimates, reducing the number of new function calls per iteration to a constant.","q":"","v":false,"source_url":"https://arxiv.org/abs/2409.10442","locator":"arXiv abstract"},{"k":"method","s":"Coordinate memory is incorporated into zeroth-order variants of Frank–Wolfe and gradient descent.","q":"","v":false,"source_url":"https://arxiv.org/abs/2409.10442","locator":"arXiv abstract"},{"k":"theoretical","s":"The analysis covers convex and nonconvex problems, as well as the Polyak–Łojasiewicz condition.","q":"","v":false,"source_url":"https://arxiv.org/abs/2409.10442","locator":"arXiv abstract"},{"k":"theoretical","s":"Deterministic and stochastic noisy oracles are considered, with corresponding complexity bounds for the different regimes.","q":"","v":false,"source_url":"https://arxiv.org/abs/2409.10442","locator":"arXiv abstract"}],"origin":"author-publication","source_url":"https://arxiv.org/abs/2409.10442","venue_url":"https://doi.org/10.1016/j.chaos.2024.115654","code_url":null,"reading_scope":"arXiv abstract"},{"id":"pub00016","ax":"2408.01848","key":null,"t":"Methods for Optimization Problems with Markovian Stochasticity and Non-Euclidean Geometry","au":"Vladimir Solodkin, Andrey Veprikov, Alexander Chernyavskiy, Aleksandr Beznosikov","y":2026,"v":"AAAI 2026","s":"The paper studies optimization with dependent Markovian observations in non-Euclidean geometry. Mirror descent is applied to convex minimization and variational inequalities.","sr":"The paper studies optimization with dependent Markovian observations in non-Euclidean geometry. Mirror descent is applied to convex minimization and variational inequalities.","ab":"The paper studies optimization with dependent Markovian observations in non-Euclidean geometry. Mirror descent is applied to convex minimization and variational inequalities.","f":"Andrey's publications/Papers and preprints","th":null,"nc":4,"ns":1,"nm":0,"c":[{"k":"method","s":"Four mirror-descent variants are adapted to stochastic observations linked by a Markov chain.","q":"","v":false,"source_url":"https://arxiv.org/abs/2408.01848","locator":"arXiv abstract"},{"k":"theoretical","s":"Convergence bounds account for observation dependence and non-Euclidean geometry rather than assuming independent Euclidean noise.","q":"","v":false,"source_url":"https://arxiv.org/abs/2408.01848","locator":"arXiv abstract"},{"k":"theoretical","s":"The paper considers smooth convex minimization and variational inequalities with a Lipschitz monotone operator.","q":"","v":false,"source_url":"https://arxiv.org/abs/2408.01848","locator":"arXiv abstract"},{"k":"theoretical","s":"Complexity lower bounds are compared with the derived upper bounds to establish optimality in the settings considered.","q":"","v":false,"source_url":"https://arxiv.org/abs/2408.01848","locator":"arXiv abstract"}],"origin":"author-publication","source_url":"https://arxiv.org/abs/2408.01848","venue_url":"https://ojs.aaai.org/index.php/AAAI/article/view/39746","code_url":null,"reading_scope":"arXiv abstract"},{"id":"pub00017","ax":"2405.02726","key":null,"t":"A Mathematical Model of the Hidden Feedback Loop Effect in Machine Learning Systems","au":"Andrey Veprikov, Alexander Afanasyev, Anton Khritankov","y":2025,"v":"Knowledge and Information Systems · 2025","s":"The hidden-feedback model describes a cycle: data train a model, its decisions change the environment and the new environment generates the next data. The paper studies the long-term effects of repeated retraining.","sr":"The hidden-feedback model describes a cycle: data train a model, its decisions change the environment and the new environment generates the next data. The paper studies the long-term effects of repeated retraining.","ab":"The hidden-feedback model describes a cycle: data train a model, its decisions change the environment and the new environment generates the next data. The paper studies the long-term effects of repeated retraining.","f":"Andrey's publications/Papers and preprints","th":null,"nc":4,"ns":1,"nm":0,"c":[{"k":"definition","s":"Hidden feedback arises when the environment's state causally depends on a trained model's predictions, changing the distribution of future data.","q":"","v":false,"source_url":"https://arxiv.org/abs/2405.02726","locator":"arXiv abstract"},{"k":"theoretical","s":"The dynamic retraining model provides sufficient conditions for convergence and limiting sets of distributions.","q":"","v":false,"source_url":"https://arxiv.org/abs/2405.02726","locator":"arXiv abstract"},{"k":"theoretical","s":"Positive and negative feedback are considered as different regimes of data-distribution evolution.","q":"","v":false,"source_url":"https://arxiv.org/abs/2405.02726","locator":"arXiv abstract"},{"k":"empirical","s":"The model's predictions are tested on two synthetic datasets. The experiments do not validate an industrial recommender system.","q":"","v":false,"source_url":"https://arxiv.org/abs/2405.02726","locator":"arXiv abstract"}],"origin":"author-publication","source_url":"https://arxiv.org/abs/2405.02726","venue_url":"https://doi.org/10.1007/s10115-025-02560-w","code_url":null,"reading_scope":"arXiv abstract"},{"id":"pub00018","ax":"2307.00392","key":null,"t":"Non-Smooth Setting of Stochastic Decentralized Convex Optimization Problem Over Time-Varying Graphs","au":"Aleksandr Lobanov, Andrew Veprikov, Georgiy Konin, Aleksandr Beznosikov, Alexander Gasnikov, Dmitry Kovalev","y":2023,"v":"Computational Management Science · 2023","s":"Decentralized convex optimization is studied on a graph whose edges change over time. Stochastic zeroth-order estimates and randomized smoothing are used for nonsmooth local functions.","sr":"Decentralized convex optimization is studied on a graph whose edges change over time. Stochastic zeroth-order estimates and randomized smoothing are used for nonsmooth local functions.","ab":"Decentralized convex optimization is studied on a graph whose edges change over time. Stochastic zeroth-order estimates and randomized smoothing are used for nonsmooth local functions.","f":"Andrey's publications/Papers and preprints","th":null,"nc":4,"ns":1,"nm":0,"c":[{"k":"definition","s":"Each agent holds its own local function and exchanges information only with neighbors in the changing communication graph.","q":"","v":false,"source_url":"https://arxiv.org/abs/2307.00392","locator":"arXiv abstract"},{"k":"method","s":"Randomized smoothing in Euclidean geometry converts the nonsmooth problem into a form suitable for zeroth-order updates.","q":"","v":false,"source_url":"https://arxiv.org/abs/2307.00392","locator":"arXiv abstract"},{"k":"theoretical","s":"Convergence bounds are obtained for stochastic decentralized convex optimization with changing connectivity.","q":"","v":false,"source_url":"https://arxiv.org/abs/2307.00392","locator":"arXiv abstract"},{"k":"empirical","s":"Numerical experiments compare the proposed methods' behavior with the predictions of the theoretical analysis.","q":"","v":false,"source_url":"https://arxiv.org/abs/2307.00392","locator":"arXiv abstract"}],"origin":"author-publication","source_url":"https://arxiv.org/abs/2307.00392","venue_url":"https://doi.org/10.1007/s10287-023-00479-7","code_url":null,"reading_scope":"arXiv abstract"},{"id":"pub00019","ax":null,"key":null,"t":"Adversarial Robustness through Wide Local Minima: A Simple Training Technique","au":"Andrey S. Veprikov, Anton S. Khritankov, Sergey A. Smirnov","y":2024,"v":"ICOMP 2024","s":"The paper connects adversarial robustness to the width of a local minimum. The authors study how training settings help find such solutions without changing the model architecture.","sr":"The paper connects adversarial robustness to the width of a local minimum. The authors study how training settings help find such solutions without changing the model architecture.","ab":"The paper connects adversarial robustness to the width of a local minimum. The authors study how training settings help find such solutions without changing the model architecture.","f":"Andrey's publications/Papers and preprints","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"method","s":"The proposed approach selects training parameters to guide optimization toward wide local minima.","q":"","v":false,"source_url":"https://openreview.net/pdf?id=oZ8j2xSWVg","locator":"Abstract and introduction, pp. 1–2"},{"k":"method","s":"The robustness approach uses training settings without changing the architecture or loss function, or adding adversarial examples to the training set.","q":"","v":false,"source_url":"https://openreview.net/pdf?id=oZ8j2xSWVg","locator":"Abstract and introduction, pp. 1–2"},{"k":"empirical","s":"The paper examines robustness to FGSM on MNIST. The result applies to that specific attack and experimental setup.","q":"","v":false,"source_url":"https://openreview.net/pdf?id=oZ8j2xSWVg","locator":"Abstract and introduction, pp. 1–2"}],"origin":"author-publication","source_url":"https://openreview.net/pdf?id=oZ8j2xSWVg","venue_url":"https://openreview.net/forum?id=oZ8j2xSWVg","code_url":null,"reading_scope":"Abstract and introduction, pp. 1–2"},{"id":"pub00020","ax":null,"key":null,"t":"On the Properties of the Limit Set of a Repeated Machine Learning Process under Feature Space Transformations","au":"Andrey S. Veprikov, Anton S. Khritankov","y":2025,"v":"Artificial Intelligence and Decision Making · 2025","s":"The paper studies when changing the feature space preserves a prediction of the long-term behavior of a repeatedly retrained system. This makes it possible to study a complex system through a simpler model.","sr":"The paper studies when changing the feature space preserves a prediction of the long-term behavior of a repeatedly retrained system. This makes it possible to study a complex system through a simpler model.","ab":"The paper studies when changing the feature space preserves a prediction of the long-term behavior of a repeatedly retrained system. This makes it possible to study a complex system through a simpler model.","f":"Andrey's publications/Papers and preprints","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"definition","s":"Under repeated machine learning, subsequent training data depend on user behavior and the model already in operation.","q":"","v":false,"source_url":"https://journals.rcsi.science/2071-8594/article/view/293493","locator":"Publisher abstract"},{"k":"theoretical","s":"The paper studies conditions for transferring predictions of asymptotic behavior between original and transformed feature spaces.","q":"","v":false,"source_url":"https://journals.rcsi.science/2071-8594/article/view/293493","locator":"Publisher abstract"},{"k":"theoretical","s":"When these conditions hold, lower-dimensional systems can model the limiting behavior of more complex systems.","q":"","v":false,"source_url":"https://journals.rcsi.science/2071-8594/article/view/293493","locator":"Publisher abstract"}],"origin":"author-publication","source_url":"https://journals.rcsi.science/2071-8594/article/view/293493","venue_url":"https://journals.rcsi.science/2071-8594/article/view/293493","code_url":null,"reading_scope":"Publisher abstract"},{"id":"pub00021","ax":null,"key":null,"t":"Zero Order Algorithm for Decentralized Optimization Problems","au":"A. S. Veprikov, E. D. Petrov, G. V. Evseev, A. N. Beznosikov","y":2024,"v":"Doklady Mathematics · 2024","s":"ZO-MARINA extends the distributed optimization method MARINA to a black-box setting. Devices use noisy local function values and exchange sparse update estimates.","sr":"ZO-MARINA extends the distributed optimization method MARINA to a black-box setting. Devices use noisy local function values and exchange sparse update estimates.","ab":"ZO-MARINA extends the distributed optimization method MARINA to a black-box setting. Devices use noisy local function values and exchange sparse update estimates.","f":"Andrey's publications/Papers and preprints","th":null,"nc":4,"ns":1,"nm":0,"c":[{"k":"method","s":"ZO-MARINA replaces exact gradients with function-value estimates and the standard compressor with differences of estimates on selected coordinates.","q":"","v":false,"source_url":"https://link.springer.com/article/10.1134/S1064562424602336","locator":"Publisher abstract"},{"k":"method","s":"Zeroth-order sparsification allows each device to use a constant number of oracle calls per iteration.","q":"","v":false,"source_url":"https://link.springer.com/article/10.1134/S1064562424602336","locator":"§1.2 Main Contributions"},{"k":"theoretical","s":"The convergence analysis covers nonconvex functions and the Polyak–Łojasiewicz condition. The resulting bounds are compared with first-order methods.","q":"","v":false,"source_url":"https://link.springer.com/article/10.1134/S1064562424602336","locator":"Publisher abstract"},{"k":"empirical","s":"Computational experiments focus on hyperparameter tuning for ResNet-18 on CIFAR-10 and SVM on mushroom and MNIST-784.","q":"","v":false,"source_url":"https://link.springer.com/article/10.1134/S1064562424602336","locator":"§1.2 Main Contributions"}],"origin":"author-publication","source_url":"https://link.springer.com/article/10.1134/S1064562424602336","venue_url":"https://link.springer.com/article/10.1134/S1064562424602336","code_url":null,"reading_scope":"Publisher abstract; §1.2 Main Contributions"},{"id":"pub00022","ax":null,"key":null,"t":"Sampling of Semiorthogonal Matrices for the Muon Algorithm","au":"E. D. Petrov, G. V. Evseev, A. V. Antonov, A. S. Veprikov, N. A. Bushkov, S. V. Moiseev, A. N. Beznosikov","y":2025,"v":"Doklady Mathematics · 2025","s":"The paper studies ways to sample semi-orthogonal matrices for zeroth-order Muon. It compares how the choice of matrix directions affects LLM fine-tuning cost and quality.","sr":"The paper studies ways to sample semi-orthogonal matrices for zeroth-order Muon. It compares how the choice of matrix directions affects LLM fine-tuning cost and quality.","ab":"The paper studies ways to sample semi-orthogonal matrices for zeroth-order Muon. It compares how the choice of matrix directions affects LLM fine-tuning cost and quality.","f":"Andrey's publications/Papers and preprints","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"method","s":"In the zeroth-order setting, Muon uses estimates from model forward passes, avoiding backpropagation and storage of its computation graph.","q":"","v":false,"source_url":"https://link.springer.com/article/10.1134/S1064562425700565","locator":"Publisher abstract"},{"k":"method","s":"Different sampling strategies for semi-orthogonal directions account for the matrix structure of the parameters when constructing an update.","q":"","v":false,"source_url":"https://link.springer.com/article/10.1134/S1064562425700565","locator":"Publisher abstract"},{"k":"empirical","s":"The paper compares sampling strategies by language model fine-tuning quality and computational efficiency.","q":"","v":false,"source_url":"https://link.springer.com/article/10.1134/S1064562425700565","locator":"Publisher abstract"}],"origin":"author-publication","source_url":"https://link.springer.com/article/10.1134/S1064562425700565","venue_url":"https://link.springer.com/article/10.1134/S1064562425700565","code_url":null,"reading_scope":"Publisher abstract"},{"id":"ref00001","ax":"2106.09685","key":null,"t":"LoRA: Low-Rank Adaptation of Large Language Models","au":"Edward J. Hu, Yelong Shen, Phillip Wallis, Zeyuan Allen-Zhu, Yuanzhi Li, Shean Wang, Lu Wang, Weizhu Chen","y":2021,"v":"arXiv · 2021","s":"LoRA trains small low-rank additions to frozen model weights. This reduces the number of trainable parameters and memory use when adapting to a new task.","sr":"LoRA trains small low-rank additions to frozen model weights. This reduces the number of trainable parameters and memory use when adapting to a new task.","ab":"LoRA trains small low-rank additions to frozen model weights. This reduces the number of trainable parameters and memory use when adapting to a new task.","f":"Other research/Related papers","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"method","s":"LoRA freezes pretrained weights and adds trainable low-rank matrices to Transformer layers.","q":"","v":false,"source_url":"https://arxiv.org/abs/2106.09685","locator":"arXiv abstract"},{"k":"empirical","s":"In experiments with RoBERTa, DeBERTa, GPT-2 and GPT-3, the authors achieve quality matching or exceeding full fine-tuning with fewer trainable parameters.","q":"","v":false,"source_url":"https://arxiv.org/abs/2106.09685","locator":"arXiv abstract"},{"k":"method","s":"The low-rank addition can be merged into the original weights, so the approach requires no extra layers at inference.","q":"","v":false,"source_url":"https://arxiv.org/abs/2106.09685","locator":"arXiv abstract"}],"origin":"related-publication","source_url":"https://arxiv.org/abs/2106.09685","venue_url":"https://arxiv.org/abs/2106.09685","code_url":null,"reading_scope":"arXiv abstract"},{"id":"ref00002","ax":"2303.10512","key":null,"t":"AdaLoRA: Adaptive Budget Allocation for Parameter-Efficient Fine-Tuning","au":"Qingru Zhang, Minshuo Chen, Alexander Bukharin, Nikos Karampatziakis, Pengcheng He, Yu Cheng, Weizhu Chen, Tuo Zhao","y":2023,"v":"arXiv · 2023","s":"AdaLoRA allocates the trainable-parameter budget across matrices according to their importance. Rather than using the same rank for every update, it removes less useful components.","sr":"AdaLoRA allocates the trainable-parameter budget across matrices according to their importance. Rather than using the same rank for every update, it removes less useful components.","ab":"AdaLoRA allocates the trainable-parameter budget across matrices according to their importance. Rather than using the same rank for every update, it removes less useful components.","f":"Other research/Related papers","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"method","s":"AdaLoRA adaptively allocates the parameter budget across weight matrices using estimates of update importance.","q":"","v":false,"source_url":"https://arxiv.org/abs/2303.10512","locator":"arXiv abstract"},{"k":"method","s":"Updates are parameterized in singular-value-decomposition form. Unimportant singular values are pruned without an expensive exact SVD.","q":"","v":false,"source_url":"https://arxiv.org/abs/2303.10512","locator":"arXiv abstract"},{"k":"empirical","s":"On language processing, question answering and generation tasks, the authors report improvements over baselines, especially under a small parameter budget.","q":"","v":false,"source_url":"https://arxiv.org/abs/2303.10512","locator":"arXiv abstract"}],"origin":"related-publication","source_url":"https://arxiv.org/abs/2303.10512","venue_url":"https://arxiv.org/abs/2303.10512","code_url":null,"reading_scope":"arXiv abstract"},{"id":"ref00003","ax":"2305.17333","key":null,"t":"Fine-Tuning Language Models with Just Forward Passes","au":"Sadhika Malladi, Tianyu Gao, Eshaan Nichani, Alex Damian, Jason D. Lee, Danqi Chen, Sanjeev Arora","y":2023,"v":"arXiv · 2023","s":"MeZO fine-tunes a language model using only forward passes, estimating the update direction from objective values. Its main goal is to save memory without backpropagation.","sr":"MeZO fine-tunes a language model using only forward passes, estimating the update direction from objective values. Its main goal is to save memory without backpropagation.","ab":"MeZO fine-tunes a language model using only forward passes, estimating the update direction from objective values. Its main goal is to save memory without backpropagation.","f":"Other research/Related papers","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"method","s":"MeZO implements zeroth-order SGD with in-place parameter changes and estimates the update through model forward passes.","q":"","v":false,"source_url":"https://arxiv.org/abs/2305.17333","locator":"arXiv abstract"},{"k":"empirical","s":"The authors test classification, multiple-choice and generation tasks. In their implementation, fine-tuning memory use is comparable to inference.","q":"","v":false,"source_url":"https://arxiv.org/abs/2305.17333","locator":"arXiv abstract"},{"k":"method","s":"The method supports full fine-tuning, LoRA and prefix tuning, and allows nondifferentiable objectives such as accuracy or F1.","q":"","v":false,"source_url":"https://arxiv.org/abs/2305.17333","locator":"arXiv abstract"}],"origin":"related-publication","source_url":"https://arxiv.org/abs/2305.17333","venue_url":"https://arxiv.org/abs/2305.17333","code_url":null,"reading_scope":"arXiv abstract"},{"id":"ref00004","ax":"1802.09568","key":null,"t":"Shampoo: Preconditioned Stochastic Tensor Optimization","au":"Vineet Gupta, Tomer Koren, Yoram Singer","y":2018,"v":"arXiv · 2018","s":"Shampoo preconditions updates using the tensor structure of the parameters. A set of matrices for individual axes replaces one enormous preconditioning matrix.","sr":"Shampoo preconditions updates using the tensor structure of the parameters. A set of matrices for individual axes replaces one enormous preconditioning matrix.","ab":"Shampoo preconditions updates using the tensor structure of the parameters. A set of matrices for individual axes replaces one enormous preconditioning matrix.","f":"Other research/Related papers","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"method","s":"Shampoo stores a separate preconditioning matrix for each dimension of a parameter tensor, contracting gradients over the other dimensions.","q":"","v":false,"source_url":"https://arxiv.org/abs/1802.09568","locator":"arXiv abstract"},{"k":"theoretical","s":"For stochastic convex optimization, the authors prove convergence guarantees using matrix trace inequalities.","q":"","v":false,"source_url":"https://arxiv.org/abs/1802.09568","locator":"arXiv abstract"},{"k":"empirical","s":"In the reported experiments, the authors observe faster convergence than the compared optimizers at comparable step time. This is a result for those tasks, not a guarantee for every model.","q":"","v":false,"source_url":"https://arxiv.org/abs/1802.09568","locator":"arXiv abstract"}],"origin":"related-publication","source_url":"https://arxiv.org/abs/1802.09568","venue_url":"https://arxiv.org/abs/1802.09568","code_url":null,"reading_scope":"arXiv abstract"},{"id":"ref00005","ax":"1610.02132","key":null,"t":"QSGD: Communication-Efficient SGD via Gradient Quantization and Encoding","au":"Dan Alistarh, Demjan Grubic, Jerry Li, Ryota Tomioka, Milan Vojnovic","y":2016,"v":"arXiv · 2016","s":"QSGD reduces gradient communication through quantization and encoding. The compression level trades communication cost against convergence time.","sr":"QSGD reduces gradient communication through quantization and encoding. The compression level trades communication cost against convergence time.","ab":"QSGD reduces gradient communication through quantization and encoding. The compression level trades communication cost against convergence time.","f":"Other research/Related papers","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"method","s":"QSGD compresses gradient updates at each node through quantization and encoding before communicating them to other training participants.","q":"","v":false,"source_url":"https://arxiv.org/abs/1610.02132","locator":"arXiv abstract"},{"k":"theoretical","s":"Under standard assumptions, the family of schemes preserves convergence guarantees and allows control of the tradeoff between message size and iteration count.","q":"","v":false,"source_url":"https://arxiv.org/abs/1610.02132","locator":"arXiv abstract"},{"k":"empirical","s":"The authors test quantization on image classification and speech recognition, reporting lower communication costs and total training time in those experiments.","q":"","v":false,"source_url":"https://arxiv.org/abs/1610.02132","locator":"arXiv abstract"}],"origin":"related-publication","source_url":"https://arxiv.org/abs/1610.02132","venue_url":"https://arxiv.org/abs/1610.02132","code_url":null,"reading_scope":"arXiv abstract"},{"id":"ref00006","ax":"2002.06673","key":null,"t":"Performative Prediction","au":"Juan C. Perdomo, Tijana Zrnic, Celestine Mendler-Dünner, Moritz Hardt","y":2020,"v":"arXiv · 2020","s":"The paper studies models whose predictions change future data. It introduces a notion of stability for repeated retraining in an environment that responds to the predictor.","sr":"The paper studies models whose predictions change future data. It introduces a notion of stability for repeated retraining in an environment that responds to the predictor.","ab":"The paper studies models whose predictions change future data. It introduces a notion of stability for repeated retraining in an environment that responds to the predictor.","f":"Other research/Related papers","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"definition","s":"A prediction is performative when decisions based on it affect the predicted outcome and the distribution of future data.","q":"","v":false,"source_url":"https://arxiv.org/abs/2002.06673","locator":"arXiv abstract"},{"k":"definition","s":"Performative stability describes an equilibrium: the model is optimal for the distribution that arises in response to deploying that model.","q":"","v":false,"source_url":"https://arxiv.org/abs/2002.06673","locator":"arXiv abstract"},{"k":"theoretical","s":"The authors study conditions under which repeated retraining converges to a stable point with nearly minimal risk, and connect the approach to strategic classification.","q":"","v":false,"source_url":"https://arxiv.org/abs/2002.06673","locator":"arXiv abstract"}],"origin":"related-publication","source_url":"https://arxiv.org/abs/2002.06673","venue_url":"https://arxiv.org/abs/2002.06673","code_url":null,"reading_scope":"arXiv abstract"},{"id":"ref00007","ax":"2406.09405","key":null,"t":"Why Warmup the Learning Rate? Underlying Mechanisms and Improvements","au":"Dayal Singh Kalra, Maissam Barkeshli","y":2024,"v":"arXiv · 2024","s":"The authors study why gradually increasing the learning rate at the start helps SGD and Adam. Warmup is linked to moving into regions that allow a larger target learning rate.","sr":"The authors study why gradually increasing the learning rate at the start helps SGD and Adam. Warmup is linked to moving into regions that allow a larger target learning rate.","ab":"The authors study why gradually increasing the learning rate at the start helps SGD and Adam. Warmup is linked to moving into regions that allow a larger target learning rate.","f":"Other research/Related papers","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"empirical","s":"In systematic SGD and Adam experiments, the main benefit of warmup is linked to the ability to use a larger target learning rate.","q":"","v":false,"source_url":"https://arxiv.org/abs/2406.09405","locator":"arXiv abstract"},{"k":"empirical","s":"Behavior during warmup depends on initialization and parameterization: landscape sharpness may initially rise or fall.","q":"","v":false,"source_url":"https://arxiv.org/abs/2406.09405","locator":"arXiv abstract"},{"k":"method","s":"The authors propose choosing the initial learning rate based on the loss-catapult mechanism and examine an initialization of Adam's variance estimate that provides similar benefits to warmup.","q":"","v":false,"source_url":"https://arxiv.org/abs/2406.09405","locator":"arXiv abstract"}],"origin":"related-publication","source_url":"https://arxiv.org/abs/2406.09405","venue_url":"https://arxiv.org/abs/2406.09405","code_url":null,"reading_scope":"arXiv abstract"},{"id":"ref00008","ax":"2409.11321","key":null,"t":"SOAP: Improving and Stabilizing Shampoo using Adam","au":"Nikhil Vyas, Depen Morwani, Rosie Zhao, Mujin Kwun, Itai Shapira, David Brandfonbrener, Lucas Janson, Sham Kakade","y":2024,"v":"arXiv · 2024","s":"SOAP applies Adam in the eigenbasis of the Shampoo preconditioner. It allows less frequent basis updates while continuing to accumulate gradient statistics between them.","sr":"SOAP applies Adam in the eigenbasis of the Shampoo preconditioner. It allows less frequent basis updates while continuing to accumulate gradient statistics between them.","ab":"SOAP applies Adam in the eigenbasis of the Shampoo preconditioner. It allows less frequent basis updates while continuing to accumulate gradient statistics between them.","f":"Other research/Related papers","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"method","s":"SOAP takes Adam steps in the preconditioner's eigenbasis, connecting coordinate-wise adaptation to Shampoo geometry.","q":"","v":false,"source_url":"https://arxiv.org/abs/2409.11321","locator":"arXiv abstract"},{"k":"method","s":"Second-moment statistics are updated at every step in the current basis. This mitigates quality degradation when eigendecompositions are recomputed infrequently.","q":"","v":false,"source_url":"https://arxiv.org/abs/2409.11321","locator":"arXiv abstract"},{"k":"empirical","s":"In pretraining language models with 360 and 660 million parameters, the authors report improvements in iteration count and time over AdamW and Shampoo in a large-batch regime.","q":"","v":false,"source_url":"https://arxiv.org/abs/2409.11321","locator":"arXiv abstract"}],"origin":"related-publication","source_url":"https://arxiv.org/abs/2409.11321","venue_url":"https://arxiv.org/abs/2409.11321","code_url":null,"reading_scope":"arXiv abstract"},{"id":"demo0001","ax":null,"key":"ivanova2025how","t":"How Long Should Warm-up Be? A Budget View","au":"Ivanova, Maria, Sokolov, Peter","y":2025,"v":"","s":"Fictional demo paper. Examines warmup as a fraction of the training budget rather than a standalone step count. Its main conclusion is that the fraction, not the absolute length, transfers across scales.","sr":"Fictional demo paper. Examines warmup as a fraction of the training budget rather than a standalone step count. Its main conclusion is that the fraction, not the absolute length, transfers across scales.","ab":"Fictional demo paper. Examines warmup as a fraction of the training budget rather than a standalone step count. Its main conclusion is that the fraction, not the absolute length, transfers across scales.","f":"Optimization/schedules","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"empirical","s":"Warmup at 0.6% of the horizon gives the best loss at three model sizes.","q":"","v":false},{"k":"theoretical","s":"The lower bound on warmup length grows as the square root of batch size.","q":"","v":false},{"k":"method","s":"The warmup stopping signal is computed from the update norm over a 100-step window.","q":"","v":false}]},{"id":"demo0002","ax":null,"key":"romanov2024warmup","t":"Warm-up Is Not About Curvature","au":"Romanov, Dmitry","y":2024,"v":"","s":"Fictional demo paper. Tests the curvature-based explanation of warmup and finds that it does not reproduce: warmup also helps when initial curvature is low.","sr":"Fictional demo paper. Tests the curvature-based explanation of warmup and finds that it does not reproduce: warmup also helps when initial curvature is low.","ab":"Fictional demo paper. Tests the curvature-based explanation of warmup and finds that it does not reproduce: warmup also helps when initial curvature is low.","f":"Optimization/schedules","th":null,"nc":2,"ns":1,"nm":0,"c":[{"k":"empirical","s":"Warmup helps even when curvature is low at the start of training.","q":"","v":false},{"k":"definition","s":"Initial curvature is measured as the Hessian's largest eigenvalue over the first ten steps.","q":"","v":false}]},{"id":"demo0003","ax":null,"key":"sokolov2025constant","t":"Constant Step Instead of Decay: What Is Lost","au":"Sokolov, Peter, Ivanova, Maria","y":2025,"v":"","s":"Fictional demo paper. Compares a constant learning rate with cosine decay at equal budget and identifies where a longer horizon closes the gap.","sr":"Fictional demo paper. Compares a constant learning rate with cosine decay at equal budget and identifies where a longer horizon closes the gap.","ab":"Fictional demo paper. Compares a constant learning rate with cosine decay at equal budget and identifies where a longer horizon closes the gap.","f":"Optimization/schedules","th":null,"nc":2,"ns":1,"nm":0,"c":[{"k":"empirical","s":"A constant learning rate trails cosine decay by 0.02 in loss at equal budget.","q":"","v":false},{"k":"empirical","s":"Doubling the horizon closes the gap.","q":"","v":false}]},{"id":"demo0004","ax":null,"key":"romanov2026short","t":"A Short Note on Schedules and Seeds","au":"Romanov, Dmitry, Ivanova, Maria","y":2026,"v":"","s":"Fictional demo paper. Discusses seed variability comparable to the gap between schedules and how many seeds are needed to detect that gap.","sr":"Fictional demo paper. Discusses seed variability comparable to the gap between schedules and how many seeds are needed to detect that gap.","ab":"Fictional demo paper. Discusses seed variability comparable to the gap between schedules and how many seeds are needed to detect that gap.","f":"Optimization/schedules","th":null,"nc":1,"ns":1,"nm":0,"c":[{"k":"empirical","s":"Variation across three seeds is 0.003 in validation loss.","q":"","v":false}]},{"id":"demo0005","ax":null,"key":"kovalenko2024second","t":"Second Moment Estimates Under Distribution Shift","au":"Kovalenko, Anna","y":2024,"v":"","s":"Fictional demo paper. Shows where the second-moment estimate stops reflecting gradient scale and proposes a diagnostic.","sr":"Fictional demo paper. Shows where the second-moment estimate stops reflecting gradient scale and proposes a diagnostic.","ab":"Fictional demo paper. Shows where the second-moment estimate stops reflecting gradient scale and proposes a diagnostic.","f":"Optimization/adaptive","th":null,"nc":1,"ns":1,"nm":0,"c":[{"k":"theoretical","s":"After a data-distribution change, the second-moment estimate lags by the duration of its averaging window.","q":"","v":false}]},{"id":"demo0006","ax":null,"key":"kovalenko2025when","t":"When Adaptive Methods Do Not Help","au":"Kovalenko, Anna, Sokolov, Peter","y":2025,"v":"","s":"Fictional demo paper. Collects cases where adaptivity provides no benefit and connects them to homogeneous gradient scales across layers.","sr":"Fictional demo paper. Collects cases where adaptivity provides no benefit and connects them to homogeneous gradient scales across layers.","ab":"Fictional demo paper. Collects cases where adaptivity provides no benefit and connects them to homogeneous gradient scales across layers.","f":"Optimization/adaptive","th":null,"nc":2,"ns":1,"nm":0,"c":[{"k":"empirical","s":"Adaptivity provides no benefit when gradient scales are homogeneous.","q":"","v":false},{"k":"method","s":"Scale homogeneity is checked using the ratio of the maximum to median norm across layers.","q":"","v":false}]},{"id":"demo0007","ax":null,"key":"ivanova2025compute","t":"Compute-Optimal Training Revisited","au":"Ivanova, Maria, Kovalenko, Anna, Romanov, Dmitry","y":2025,"v":"","s":"Fictional demo paper. Reexamines the relationship between model size and data volume at fixed budget and refines the exponent at long horizons.","sr":"Fictional demo paper. Reexamines the relationship between model size and data volume at fixed budget and refines the exponent at long horizons.","ab":"Fictional demo paper. Reexamines the relationship between model size and data volume at fixed budget and refines the exponent at long horizons.","f":"LLM/scaling","th":null,"nc":2,"ns":1,"nm":0,"c":[{"k":"empirical","s":"At long horizons, the optimal data-to-parameter ratio is higher than the classical estimate.","q":"","v":false},{"k":"theoretical","s":"The scaling-law exponent is robust to changes in the learning-rate schedule.","q":"","v":false}]},{"id":"demo0008","ax":null,"key":"sokolov2026cheap","t":"Cheap Proxies for Scaling Laws","au":"Sokolov, Peter","y":2026,"v":"","s":"Fictional demo paper. Proposes estimating a scaling law from short runs and shows where that estimate fails.","sr":"Fictional demo paper. Proposes estimating a scaling law from short runs and shows where that estimate fails.","ab":"Fictional demo paper. Proposes estimating a scaling law from short runs and shows where that estimate fails.","f":"LLM/scaling","th":null,"nc":2,"ns":1,"nm":0,"c":[{"k":"method","s":"The scaling law is estimated from runs lasting one tenth of the horizon.","q":"","v":false},{"k":"empirical","s":"Short-run estimates fail at scales where the schedule changes.","q":"","v":false}]},{"id":"demo0009","ax":null,"key":"demo2026example9","t":"Gradient Clipping During Warm-up","au":"Demo Methods Group (fictional authors)","y":2026,"v":"","s":"Fictional demo paper. Clipping and warmup affect different indicators of stability.","sr":"Fictional demo paper. Clipping and warmup affect different indicators of stability.","ab":"Fictional demo paper. Clipping and warmup affect different indicators of stability.","f":"Optimization/stability","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"empirical","s":"Clipping reduces spike frequency but does not determine warmup length.","q":"","v":false},{"k":"method","s":"The comparison uses the same data order and budget.","q":"","v":false},{"k":"definition","s":"A spike is a norm value above a prespecified threshold.","q":"","v":false}]},{"id":"demo0010","ax":null,"key":"demo2026example10","t":"Short Windows and False Stops","au":"Demo Methods Group (fictional authors)","y":2026,"v":"","s":"Fictional demo paper. A narrow window reacts faster to noise in the update norm.","sr":"Fictional demo paper. A narrow window reacts faster to noise in the update norm.","ab":"Fictional demo paper. A narrow window reacts faster to noise in the update norm.","f":"Optimization/stability","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"empirical","s":"On the demo trajectories, a 20-step window produces more false stops than a 100-step window.","q":"","v":false},{"k":"method","s":"The false-stop rate is measured on independent control trajectories.","q":"","v":false},{"k":"definition","s":"A false stop is defined before the window width is chosen.","q":"","v":false}]},{"id":"demo0011","ax":null,"key":"demo2026example11","t":"Numerical Precision at the Start of Training","au":"Demo Methods Group (fictional authors)","y":2026,"v":"","s":"Fictional demo paper. Numerical precision is tested together with the schedule.","sr":"Fictional demo paper. Numerical precision is tested together with the schedule.","ab":"Fictional demo paper. Numerical precision is tested together with the schedule.","f":"Optimization/stability","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"empirical","s":"The demo BF16/FP32 pair has a small quality gap and different memory use.","q":"","v":false},{"k":"method","s":"Data, seed and update count are fixed for the comparison.","q":"","v":false},{"k":"definition","s":"A non-finite value is recorded as a failure, not as a poor loss.","q":"","v":false}]},{"id":"demo0012","ax":null,"key":"demo2026example12","t":"Warm-up Transfer Across Two Corpora","au":"Demo Methods Group (fictional authors)","y":2026,"v":"","s":"Fictional demo paper. Transfer across corpora requires a new control.","sr":"Fictional demo paper. Transfer across corpora requires a new control.","ab":"Fictional demo paper. Transfer across corpora requires a new control.","f":"LLM/data","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"empirical","s":"Two completed pairs show a small gap; the third is still running.","q":"","v":false},{"k":"method","s":"The comparison is between transferring a setting and tuning on the new corpus.","q":"","v":false},{"k":"definition","s":"The preliminary result states the number of completed pairs.","q":"","v":false}]},{"id":"demo0013","ax":null,"key":"demo2026example13","t":"Data Order as a Control Variable","au":"Demo Methods Group (fictional authors)","y":2026,"v":"","s":"Fictional demo paper. Data order can obscure a schedule's effect.","sr":"Fictional demo paper. Data order can obscure a schedule's effect.","ab":"Fictional demo paper. Data order can obscure a schedule's effect.","f":"LLM/data","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"empirical","s":"In the demo comparison, changing data order produced variability comparable to the schedule effect.","q":"","v":false},{"k":"method","s":"The paired design uses the same data order for both methods.","q":"","v":false},{"k":"definition","s":"A seed defines a reproducible order but does not replace a dataset description.","q":"","v":false}]},{"id":"demo0014","ax":null,"key":"demo2026example14","t":"Separate Validation for Schedule Selection","au":"Demo Methods Group (fictional authors)","y":2026,"v":"","s":"Fictional demo paper. Setting selection and final evaluation require different data.","sr":"Fictional demo paper. Setting selection and final evaluation require different data.","ab":"Fictional demo paper. Setting selection and final evaluation require different data.","f":"LLM/data","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"empirical","s":"The demo shows optimistic quality estimates after repeated tuning on the same validation set.","q":"","v":false},{"k":"method","s":"A setting is chosen on an intermediate dataset and evaluated on a held-out set.","q":"","v":false},{"k":"definition","s":"Evaluation leakage occurs when the final evaluation set is used to select parameters.","q":"","v":false}]},{"id":"demo0015","ax":null,"key":"demo2026example15","t":"Restarting Without Changing the Next Step","au":"Demo Methods Group (fictional authors)","y":2026,"v":"","s":"Fictional demo paper. Weights alone are not enough for a restart.","sr":"Fictional demo paper. Weights alone are not enough for a restart.","ab":"Fictional demo paper. Weights alone are not enough for a restart.","f":"LLM/reproducibility","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"empirical","s":"A complete checkpoint reproduces the next step in a deterministic demo.","q":"","v":false},{"k":"method","s":"Weights, optimizer, random number generators and data position are saved.","q":"","v":false},{"k":"definition","s":"Restart verification compares uninterrupted and restored runs.","q":"","v":false}]},{"id":"demo0016","ax":null,"key":"demo2026example16","t":"Accumulation and the Schedule Clock","au":"Demo Methods Group (fictional authors)","y":2026,"v":"","s":"Fictional demo paper. The schedule index must track optimizer updates.","sr":"Fictional demo paper. The schedule index must track optimizer updates.","ab":"Fictional demo paper. The schedule index must track optimizer updates.","f":"LLM/reproducibility","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"empirical","s":"A demo run indexed by microbatches ended warmup four times earlier.","q":"","v":false},{"k":"method","s":"The index advances after an optimizer step.","q":"","v":false},{"k":"definition","s":"Four microbatches can form one effective batch.","q":"","v":false}]},{"id":"demo0017","ax":null,"key":"demo2026example17","t":"Reporting Failed Runs","au":"Demo Methods Group (fictional authors)","y":2026,"v":"","s":"Fictional demo paper. A failed run remains part of the research history.","sr":"Fictional demo paper. A failed run remains part of the research history.","ab":"Fictional demo paper. A failed run remains part of the research history.","f":"LLM/reproducibility","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"empirical","s":"The out-of-memory failure gave no quality estimate but established a configuration limit.","q":"","v":false},{"k":"method","s":"Failure reason, last step and the next verifiable plan are saved separately.","q":"","v":false},{"k":"definition","s":"A failed run and a refuted scientific claim are different records.","q":"","v":false}]},{"id":"demo0018","ax":null,"key":"demo2026example18","t":"Time to a Shared Quality Target","au":"Demo Methods Group (fictional authors)","y":2026,"v":"","s":"Fictional demo paper. Time comparisons require a shared quality threshold.","sr":"Fictional demo paper. Time comparisons require a shared quality threshold.","ab":"Fictional demo paper. Time comparisons require a shared quality threshold.","f":"Evaluation/efficiency","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"empirical","s":"Across the five demo runs, cosine decay reached the threshold before the constant learning rate.","q":"","v":false},{"k":"method","s":"The threshold, budget and treatment of runs that do not reach it are fixed in advance.","q":"","v":false},{"k":"definition","s":"Time to threshold is not the total training duration.","q":"","v":false}]},{"id":"demo0019","ax":null,"key":"demo2026example19","t":"Why One Seed Can Reverse the Ranking","au":"Demo Methods Group (fictional authors)","y":2026,"v":"","s":"Fictional demo paper. One random run can select a different winner.","sr":"Fictional demo paper. One random run can select a different winner.","ab":"Fictional demo paper. One random run can select a different winner.","f":"Evaluation/efficiency","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"empirical","s":"In the demo table, the first-seed winner lost by the mean across five seeds.","q":"","v":false},{"k":"method","s":"The mean, variability and all individual results are reported.","q":"","v":false},{"k":"definition","s":"A paired difference compares methods within the same seed.","q":"","v":false}]},{"id":"demo0020","ax":null,"key":"demo2026example20","t":"Memory Budgets and Effective Batch Size","au":"Demo Methods Group (fictional authors)","y":2026,"v":"","s":"Fictional demo paper. A memory limit does not require changing the effective batch size.","sr":"Fictional demo paper. A memory limit does not require changing the effective batch size.","ab":"Fictional demo paper. A memory limit does not require changing the effective batch size.","f":"Evaluation/efficiency","th":null,"nc":3,"ns":1,"nm":0,"c":[{"k":"empirical","s":"In the demo, gradient accumulation reduced peak memory at the same effective batch size.","q":"","v":false},{"k":"method","s":"The comparison fixes gradient normalization and update count.","q":"","v":false},{"k":"definition","s":"The microbatch determines memory per pass; the effective batch determines the data used for one step.","q":"","v":false}]}],"folders":[{"f":"Andrey's publications/Papers and preprints","n":22},{"f":"Other research/Related papers","n":8},{"f":"Optimization/schedules","n":4},{"f":"Optimization/adaptive","n":2},{"f":"LLM/scaling","n":2},{"f":"Optimization/stability","n":3},{"f":"LLM/data","n":3},{"f":"LLM/reproducibility","n":3},{"f":"Evaluation/efficiency","n":3}],"links":[]};
